const items = $input.all();
const results = [];

for (const item of items) {
  const json = item.json;

  // Parse the return_items back from JSON string
  let returnItems = [];
  try {
    returnItems = JSON.parse(json.return_items || '[]');
  } catch (e) {
    returnItems = [];
  }

  let action = 'NO_OP';
  let reason = 'Unknown';
  let pause_weeks = 0;

  // Check if this return has items
  if (!returnItems || returnItems.length === 0) {
    action = 'NO_OP';
    reason = 'No items in return';
  } else {
    // Check outcomes - if it includes "refund", we act. If "exchange", we don't.
    // Note: We need to pass outcomes from the webhook payload
    // Since we didn't extract it in Node 3, let's work with what we have

    // For AfterShip: check if all items are being refunded
    const allRefunded = returnItems.every(i => {
      const refundQty = parseInt(i.refund_quantity) || 0;
      const orderedQty = parseInt(i.ordered_quantity) || 1;
      return refundQty >= orderedQty;
    });

    const someRefunded = returnItems.some(i => {
      const refundQty = parseInt(i.refund_quantity) || 0;
      return refundQty > 0;
    });

    if (!someRefunded) {
      action = 'NO_OP';
      reason = 'No items being refunded';
    } else if (allRefunded) {
      action = 'CANCEL';
      reason = 'Full refund - all items returned';
    } else {
      action = 'PAUSE';
      reason = 'Partial refund - some items kept';
      pause_weeks = 4;
    }
  }

  results.push({
    json: {
      ...json,
      action,
      reason,
      pause_weeks,
      return_items_count: returnItems.length,
      product_titles: returnItems.map(i => i.product_title).join(', ')
    }
  });
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const json = item.json;

  // Now this will have the actual product ID!
  const returnedProductId = json.returned_product_id || '';
  const returnedSku = json.returned_sku || '';

  const allSubscriptions = json.subscriptions || [];

  // Match by product ID (Recharge stores it as external_product_id.ecommerce)
  const matchingSubscription = allSubscriptions.find(sub => {
    const subProductId = sub.external_product_id?.ecommerce || '';
    return subProductId.toString() === returnedProductId.toString();
  });

  // Fallback: match by SKU
  const matchingBySku = !matchingSubscription ? allSubscriptions.find(sub => {
    return sub.sku && sub.sku === returnedSku && returnedSku !== '';
  }) : null;

  const finalMatch = matchingSubscription || matchingBySku;

  results.push({
    json: {
      ...json,
      matching_subscription: finalMatch || null,
      matching_subscription_id: finalMatch ? finalMatch.id : null,
      total_subscriptions_found: allSubscriptions.length,
      returned_product_id: returnedProductId,
      match_found: finalMatch ? true : false,
      match_reason: finalMatch 
        ? (matchingSubscription ? 'Matched by product ID' : 'Matched by SKU') 
        : 'No subscription found for returned product ID: ' + returnedProductId
    }
  });
}

return results;

